import * as THREE from './vendor/three.module.js';
import {traceImpact,segmentBoxFraction} from './combat-collision.js?v=robot-experiments-108';
import {terrainHeight,traceTerrain} from './runner-motion.js?v=overall-performance-238';
const v=p=>new THREE.Vector3().copy(p);
export function tagged(object,tag){return object?.[tag]===true||object?.tags?.includes(tag)||object?.userData?.[tag]===true||object?.userData?.tags?.includes(tag);}
export class ShurikenWorld {
 constructor(config,{getSections,getEnemies,getBounds,isHazard=()=>false,traceThreat=()=>null}){Object.assign(this,{config,getSections,getEnemies,getBounds,isHazard,traceThreat});}
 solid(a,b,radius=0,ignore=null){const hit=traceImpact(a,b,{sections:ignore?this.getSections().filter(s=>!ignore.has(s)):this.getSections(),ground:true,radius}),terrain=traceTerrain(a,b,radius);return terrain&&(!hit||terrain.t<hit.t)?terrain:hit;}
 flightSolid(a,b,radius=0,pierces=false){const enemySections=pierces?new Set(this.getEnemies().filter(u=>u.alive).flatMap(u=>u.entity.sections||[])):null;return this.solid(a,b,radius,enemySections);}
 enemies(a,b,radius=0){return this.getEnemies().filter(u=>u.alive&&!u.hidden&&!u.dashPhased).map(unit=>traceImpact(a,b,{targets:[unit],ground:false,radius,movingTargets:true})).filter(Boolean).sort((a,b)=>a.t-b.t);}
 forbidden(hit){return tagged(hit?.section,this.config.collision.untelTag)||hit?.section?.teleportable===false;}
 normal(hit){if(!hit?.section)return new THREE.Vector3(0,1,0);const s=hit.section,q=new THREE.Quaternion().copy(s.body?.quaternion||{x:0,y:0,z:0,w:1}),center=v(s.body?.position||s),local=v(hit.point).sub(center).applyQuaternion(q.clone().invert());let best=Infinity,result=new THREE.Vector3();for(let i=0;i<3;i++){const axis=['x','y','z'][i],delta=Math.abs(Math.abs(local[axis])-s.size[i]/2);if(delta<best){best=delta;result.set(0,0,0);result[axis]=Math.sign(local[axis])||1;}}return result.applyQuaternion(q);}
 prepare(center){const c=this.config.resolver,reach=Math.max(c.forward,c.backward,c.surfacePush)+c.height;this.near=this.getSections().filter(s=>!s.hidden&&!s.collisionDisabled&&v(s.body?.position||s).distanceTo(center)<Math.hypot(...s.size)/2+reach);}
 space(foot){const c=this.config.resolver,b=this.getBounds(),floor=terrainHeight(foot.x,foot.z);if(foot.x<b.minX+c.radius||foot.x>b.maxX-c.radius||foot.z<b.minZ+c.radius||foot.z>b.maxZ-c.radius)return{valid:false,reason:'outside arena'};if(foot.y<floor-c.skin)return{valid:false,reason:'below ground'};if(this.isHazard(foot))return{valid:false,reason:'hazard'};
  const a=v(foot).add(new THREE.Vector3(0,c.radius+c.skin*2,0)),z=v(foot).add(new THREE.Vector3(0,c.height-c.radius,0)),hit=traceImpact(a,z,{sections:this.near||this.getSections(),targets:this.getEnemies().filter(u=>u.alive&&!u.hidden&&!u.dashPhased),ground:false,radius:c.radius+c.skin});if(hit)return{valid:false,reason:hit.unit?'enemy overlap':'solid geometry',hit};return{valid:true,reason:'clear capsule'};
 }
 resolve(star){const c=this.config.resolver,anchor=this.config.arrival.anchorHeight,base=v(star.position).add(new THREE.Vector3(0,-anchor,0)),floor=terrainHeight(base.x,base.z);base.y=Math.max(floor,base.y);this.prepare(star.position);const samples=[],test=(point,type)=>{const check=this.space(point);samples.push({point:point.clone(),valid:check.valid,reason:check.reason,type});return check.valid?{valid:true,point:point.clone(),samples,reason:check.reason}:null;};let result=test(base,'current');if(result)return result;const containing=new Set((this.near||[]).filter(s=>segmentBoxFraction(star.position,star.position,s.body?.position||s,{x:s.size[0]/2,y:s.size[1]/2,z:s.size[2]/2},s.body?.quaternion,0)!==null));if([...containing].some(s=>this.forbidden({section:s})))return{valid:false,point:base,samples,reason:'unteleportable surface'};
  // Never search through a wall to reach a point on its opposite side.
  for(const [sign,distance]of[[1,c.forward],[-1,Math.min(c.backward,star.travelled)]]){const end=v(star.position).addScaledVector(star.dir,distance*sign),block=this.solid(star.position,end,star.radius,containing),limit=block?distance*Math.max(0,block.t)-c.skin:distance;for(let d=c.step;d<=limit+1e-6;d+=c.step){const point=base.clone().addScaledVector(star.dir,d*sign);point.y=Math.max(terrainHeight(point.x,point.z),point.y);result=test(point,sign>0?'past enemy':'path backup');if(result)return result;}}
  const surface=star.surface||([...containing].length?{section:[...containing][0],point:star.position}:null);if(surface){const n=this.normal(surface);for(let d=c.step;d<=c.surfacePush+1e-6;d+=c.step){result=test(base.clone().addScaledVector(n,d),'surface clearance');if(result)return result;}}
  return{valid:false,point:base,samples,reason:samples.at(-1)?.reason||'no clear landing'};
 }
 support(foot){const c=this.config.resolver,a=v(foot).add(new THREE.Vector3(0,c.floorProbe,0)),b=v(foot).add(new THREE.Vector3(0,-c.floorProbe,0)),hit=this.solid(a,b,0);return hit&&this.normal(hit).y>.65?hit:null;}
 nearest(unit,point){let best=null;for(const shape of unit.shapes){const q=new THREE.Quaternion().copy(shape.rotation||{x:0,y:0,z:0,w:1}),p=v(point).sub(shape.center).applyQuaternion(q.clone().invert());for(const axis of['x','y','z'])p[axis]=THREE.MathUtils.clamp(p[axis],-shape.half[axis],shape.half[axis]);p.applyQuaternion(q).add(shape.center);const distance=p.distanceTo(point);if(!best||distance<best.distance)best={point:p,distance,part:shape.part};}return best;}
}
